def _poll_queue(self):
    if self._shutdown_requested: return
    try:
        while True:
            task = self.task_queue.get_nowait()
            if isinstance(task, tuple):
                func, args = task
                func(*args)
    except queue.Empty:
        pass
    finally:
        self.root.after(50, self._poll_queue)
